function commerceErrorText(code:string,bn:boolean){
 const t=(en:string,be:string)=>bn?be:en;
 if(code.startsWith("Saved, but refresh failed")||code.startsWith("সংরক্ষিত হয়েছে"))return t("Saved successfully. Refresh to see the latest data.","সংরক্ষণ হয়েছে। সর্বশেষ তথ্য দেখতে রিফ্রেশ করুন।");
 if(/UNKNOWN|RECONCILE/.test(code))return t("Check this shipment with the courier before trying another booking. Record the existing consignment or confirm that no active booking exists.","আবার বুকিংয়ের আগে কুরিয়ারের কাছে মিলিয়ে নিন। আগের কনসাইনমেন্ট লিখুন, অথবা কোনো সক্রিয় বুকিং নেই নিশ্চিত করুন।");
 if(/WOOCOMMERCE.*CURRENCY/.test(code))return t("The business currency must be confirmed as BDT before importing prices. Check currency read access or use a reviewed CSV/XLSX file.","দাম আনার আগে ব্যবসার মুদ্রা BDT নিশ্চিত হতে হবে। মুদ্রা পড়ার অনুমতি দেখুন অথবা যাচাই করা CSV/XLSX দিন।");
 if(/INTEGRATION_NOT_CONFIGURED/.test(code))return t("Connect this courier or business first.","আগে কুরিয়ার বা ব্যবসাটি যুক্ত করুন।");
 if(/SCAN|PRIVATE_STORAGE/.test(code))return t("Secure photo storage or scanning is unavailable. Your product draft is preserved.","ছবি সংরক্ষণ বা নিরাপত্তা পরীক্ষা এখন চালু নেই। পণ্যের খসড়া রাখা আছে।");
 if(/FORBIDDEN|UNAUTHENTICATED|ACCESS_DENIED/.test(code))return t("Your current access does not allow this action. Sign in or ask the business owner to review your role.","আপনার বর্তমান অনুমতিতে কাজটি করা যাবে না। সাইন ইন করুন অথবা মালিককে অনুমতি দেখতে বলুন।");
 if(/STALE_BUSINESS/.test(code))return t("The selected business changed. Reopen this page in the intended business.","বাছাই করা ব্যবসা বদলেছে। সঠিক ব্যবসায় এই পৃষ্ঠা আবার খুলুন।");
 if(/CHANGED|CONFLICT/.test(code))return t("This record changed or its reference is already used. Refresh and review before saving again.","রেকর্ড বদলেছে অথবা রেফারেন্সটি ব্যবহৃত হয়েছে। রিফ্রেশ করে দেখে আবার সংরক্ষণ করুন।");
 if(/RATE|LIMIT/.test(code))return t("A limit was reached. Review quantities or wait briefly before retrying.","সীমা অতিক্রম হয়েছে। পরিমাণ দেখুন অথবা একটু পরে চেষ্টা করুন।");
 if(/INVALID|VALIDATION|REQUIRED|COLUMNS|UNSUPPORTED|UNCLOSED|EXPIRY/.test(code))return t("Check the fields, stock, dates and permitted status change. Nothing from this attempt was saved.","ঘরগুলো, মজুত, তারিখ ও অবস্থার পরিবর্তন মিলিয়ে দেখুন। এই চেষ্টায় কিছু সংরক্ষিত হয়নি।");
 if(/UNCONFIRMED|RECOVERY/.test(code))return t("Resolve the unconfirmed operation before making another change.","নতুন পরিবর্তনের আগে অনিশ্চিত কাজটির ফল মিলিয়ে নিন।");
 return /[A-Z]{2,}_[A-Z_]+/.test(code)?t("The latest information is unavailable. Keep your draft and retry refresh.","সর্বশেষ তথ্য পাওয়া যাচ্ছে না। খসড়া রেখে আবার রিফ্রেশ করুন।"):code;
}
function printOrderSlip(id:string){
 const source=document.getElementById(id);if(!source)return;const frame=document.createElement("iframe");frame.style.position="fixed";frame.style.width="0";frame.style.height="0";frame.style.border="0";frame.title="Order packing slip";document.body.appendChild(frame);
 const doc=frame.contentDocument;if(!doc){frame.remove();return;}const clone=source.cloneNode(true) as HTMLElement;clone.querySelectorAll(`.${styles.noPrint},button`).forEach(node=>node.remove());const css=doc.createElement("style");css.textContent="body{font:14px/1.6 sans-serif;color:#111;background:white;padding:24px}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #ccc;padding:10px}svg{max-width:100%}small{display:block}h2{margin:0}article{width:100%}";doc.head.appendChild(css);doc.body.appendChild(clone);if(frame.contentWindow){frame.contentWindow.onafterprint=()=>frame.remove();frame.contentWindow.focus();frame.contentWindow.print();}setTimeout(()=>frame.remove(),30000);
}
function MoneyInput({value,onChange,required=true,percent=false}:{value:unknown;onChange:(value:number|null)=>void;required?:boolean;percent?:boolean}){
 const [text,setText]=useState(value===null||value===undefined||value===""?"":(Number(value)/100).toFixed(2));
 return <input type="number" min={0} max={percent?100:1000000000} step="0.01" required={required} value={text} onChange={e=>{const raw=e.target.value;setText(raw);if(raw===""){e.target.setCustomValidity("");onChange(null);return;}if(!/^[0-9]{1,10}(\.[0-9]{0,2})?$/.test(raw)){e.target.setCustomValidity("Use at most two decimal places.");onChange(null);return;}e.target.setCustomValidity("");const [whole,fraction=""]=raw.split(".");onChange(Number(whole)*100+Number((fraction+"00").slice(0,2)));}}/>;
}
